changeSet.sql:
UPDATE customer SET city = 'Santa Branca'
    WHERE name = 'PREFEITURA MUNICIPAL DE SANTA BRANCA' AND (city IS NULL OR city = '');

UPDATE customer SET city = 'Tremembé'
    WHERE name = 'PREFEITURA MUNICIPAL DA ESTANCIA TURISTICA DE TREMEMBE' AND (city IS NULL OR city = '');

UPDATE customer SET city = 'Camanducaia'
    WHERE name IN ('PREFEITURA MUNICIPAL DE CAMANDUCAIA', 'PREFEITURA MUNICIPAL DE CAMANDUCAIA - SEDE')
    AND (city IS NULL OR city = '');

UPDATE customer SET city = 'São José dos Campos'
    WHERE name IN (
        'PREFEITURA MUNICIPAL DE SAO JOSE DOS CAMPOS',
        'PREFEITURA MUNICIPAL DE SAO JOSE DOS CAMPOS - DEMAIS',
        'PREFEITURA MUNICIPAL DE SJC - MATRIZ',
        'CAMARA MUNICIPAL DE SAO JOSE DOS CAMPOS',
        'AEROPORTO INTERNACIONAL DE SJC'
    ) AND (city IS NULL OR city = '');

UPDATE customer SET city = 'Caçapava'
    WHERE name IN ('GCM - GUARDA CIVIL MUNICIPAL DE CACAPAVA', 'TERMINAL RODOVIARIO DE CACAPAVA')
    AND (city IS NULL OR city = '');
